{
  "name": "@rasyid_rafi/opencode-agent-harness-core",
  "version": "0.1.0",
  "description": "Harness-agnostic adapter contract for running external agent harnesses inside OpenCode",
  "license": "MIT",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./testing": {
      "types": "./dist/testing/index.d.ts",
      "import": "./dist/testing/index.js",
      "default": "./dist/testing/index.js"
    }
  },
  "files": [
    "dist",
    "docs",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "bun test",
    "check": "tsc --noEmit -p tsconfig.json && bun test",
    "prepublishOnly": "npm run build"
  },
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "@types/node": "^22.15.0",
    "typescript": "^5.9.3"
  },
  "engines": {
    "bun": ">=1.4.4",
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "agent-harness",
    "adapter",
    "contract",
    "muse-code",
    "antigravity"
  ]
}

export * from "./adapter.js";
export * from "./capabilities.js";
export * from "./entities.js";
export * from "./errors.js";
export * from "./events.js";
export * from "./ids.js";
export * from "./tool-bridge.js";
//# sourceMappingURL=index.js.map

export * from "./assertions.js";
export * from "./conformance.js";
export * from "./scripted-adapter.js";
//# sourceMappingURL=index.js.map
